{
    use std::{cell::RefCell, collections::BTreeMap, rc::Rc, task::{Context, Poll, Waker}};
    fn ready<T: 'static>(mut future: crate::LocalFuture<'static, T>) -> T {
        match future.as_mut().poll(&mut Context::from_waker(Waker::noop())) {
            Poll::Ready(value) => value,
            Poll::Pending => panic!("CACHE-FIXTURE actual operation must complete on ready memory store"),
        }
    }
    #[derive(Default)]
    struct Store {
        values: RefCell<BTreeMap<String, String>>,
        calls: RefCell<Vec<(String, String)>>,
        writes: RefCell<Vec<(String, String)>>,
    }
    impl crate::CandleCacheKeyValueStore for Store {
        fn get(&self, key: String) -> crate::LocalFuture<'static, Result<Option<String>, String>> {
            self.calls.borrow_mut().push(("get".into(), key.clone()));
            let value = self.values.borrow().get(&key).cloned();
            Box::pin(async move { Ok(value) })
        }
        fn set(&self, key: String, value: String) -> crate::LocalFuture<'static, Result<(), String>> {
            self.calls.borrow_mut().push(("set".into(), key.clone()));
            self.writes.borrow_mut().push((key.clone(), value.clone()));
            self.values.borrow_mut().insert(key, value);
            Box::pin(async { Ok(()) })
        }
        fn delete(&self, key: String) -> crate::LocalFuture<'static, Result<(), String>> {
            self.calls.borrow_mut().push(("delete".into(), key.clone()));
            self.values.borrow_mut().remove(&key);
            Box::pin(async { Ok(()) })
        }
        fn list_keys(&self, prefix: String) -> crate::LocalFuture<'static, Result<Vec<String>, String>> {
            self.calls.borrow_mut().push(("list".into(), prefix.clone()));
            let keys: Vec<_> = self.values.borrow().keys().filter(|key| key.starts_with(&prefix)).cloned().collect();
            Box::pin(async move { Ok(keys) })
        }
    }
    fn candle(native: &safe_cex_types::Candle) -> serde_json::Value {
        let fields = [native.timestamp, native.open, native.high, native.low, native.close, native.volume];
        serde_json::json!({"bits":fields.map(|value|format!("{:016x}",value.to_bits())),"lastSide":match native.last_side { Some(safe_cex_types::OrderSide::Buy)=>Some("buy"),Some(safe_cex_types::OrderSide::Sell)=>Some("sell"),None=>None }})
    }
    fn chunks(native: &crate::Chunks) -> serde_json::Value {
        serde_json::json!(native.iter().map(|(key, values)|(key.to_string(), values.iter().map(|value|value.as_ref().map(candle)).collect::<Vec<_>>())).collect::<Vec<_>>())
    }
    fn assert_native(native: &crate::Chunks) {
        assert_eq!(native.keys().copied().collect::<Vec<_>>(), [0, 1], "CACHE-NATIVE independent chunk keys");
        for (key, occupied) in [(0, [true, false, true, false]), (1, [true, false, false, false])] {
            assert_eq!(native[&key].len(), 4, "CACHE-NATIVE independent sparse width");
            assert_eq!(native[&key].iter().map(Option::is_some).collect::<Vec<_>>(), occupied, "CACHE-NATIVE independent sparse occupancy");
        }
        let expected: [(i64,usize,[f64;6],Option<safe_cex_types::OrderSide>);3] = [
            (0,0,[0.0,11.25,19.5,7.75,13.125,23.5],Some(safe_cex_types::OrderSide::Buy)),
            (0,2,[120000.0,31.25,39.5,27.75,33.125,43.5],Some(safe_cex_types::OrderSide::Sell)),
            (1,0,[240000.0,51.25,59.5,47.75,53.125,63.5],None),
        ];
        let mut checked = 0;
        for (key, slot, fields, last_side) in expected {
            let value = native[&key][slot].as_ref().expect("CACHE-NATIVE independently named occupied slot");
            let actual = [value.timestamp,value.open,value.high,value.low,value.close,value.volume];
            assert_eq!(actual.map(f64::to_bits), fields.map(f64::to_bits), "CACHE-NATIVE actual decoded candle field identities");
            assert_eq!(value.last_side,last_side,"CACHE-NATIVE actual decoded last-side identity");
            checked += 1;
        }
        assert_eq!(checked,3,"CACHE-NATIVE independent candle comparisons");
    }
    let store = Rc::new(Store::default());
    for (key, raw) in [
        ("review::market::0", r#"{"candles":[{"timestamp":0,"open":11.25,"high":19.5,"low":7.75,"close":13.125,"volume":23.5,"lastSide":"buy"},null,{"timestamp":null,"open":1,"high":2,"low":3,"close":4,"volume":5},{"timestamp":60000,"high":9,"low":7,"close":8,"volume":6},{"timestamp":120000,"open":31.25,"high":39.5,"low":27.75,"close":33.125,"volume":43.5,"lastSide":"sell"},{"timestamp":240000,"open":91,"high":92,"low":90,"close":91,"volume":99}]}"#),
        ("review::market::1",r#"{"candles":[{"timestamp":240000,"open":51.25,"high":59.5,"low":47.75,"close":53.125,"volume":63.5}]}"#),
        ("review::market::2","not JSON"),
        ("review::market::3",r#"{"candles":null}"#),
        ("review::market::9223372036854775808","{}"),
        ("review::market::junk","{}"),
        ("other::market::0","foreign namespace"),
    ] { store.values.borrow_mut().insert(key.into(),raw.into()); }
    let runtime = crate::CacheRuntime {
        now_ms: Rc::new(||123.0),
        sleep: Rc::new(|_|Box::pin(async {})),
        spawn: Rc::new(|task|ready(task)),
    };
    let backend = $type::new(store.clone(),Some("review".into()),runtime);
    let options = crate::CandleCacheChunkAccessOptions {chunk_size:4,interval_seconds:60.0};
    let mode = $value.as_str().expect("authored direct/trait mode");
    assert!(matches!(mode,"direct"|"trait"),"CACHE-FIXTURE known call route");
    let direct = mode == "direct";
    let native = ready(if direct {backend.load_chunks("market".into(),vec![0,1,2,3],options)} else {crate::CandleCacheBackend::load_chunks(&backend,"market".into(),vec![0,1,2,3],options)}.expect("CACHE-FIXTURE concrete load capability")).expect("CACHE-FIXTURE ready load");
    assert_native(&native);
    let loaded = ready(if direct {backend.load_all_chunks("market".into(),options)} else {crate::CandleCacheBackend::load_all_chunks(&backend,"market".into(),options)}.expect("CACHE-FIXTURE concrete listing capability")).expect("CACHE-FIXTURE ready listing");
    assert_native(&loaded.chunks);
    assert_eq!(loaded.refused_keys,["review::market::9223372036854775808"],"CACHE-NATIVE independent refused source key");
    let load_projection = chunks(&native);
    let listing_projection = chunks(&loaded.chunks);
    // Every actual decoded load field assertion above runs BEFORE persist's
    // serialization or any subsequent persisted wire inspection.
    ready(if direct {backend.persist_chunks("written".into(),native,options)} else {crate::CandleCacheBackend::persist_chunks(&backend,"written".into(),native,options)}).expect("CACHE-FIXTURE ready persistence");
    let persisted:Vec<_> = store.writes.borrow().iter().map(|(key,raw)| {
        let record:crate::CandleCacheChunkRecord=serde_json::from_str(raw).expect("CACHE-FIXTURE persisted record JSON");
        (key.clone(),record.candles.iter().map(candle).collect::<Vec<_>>(),format!("{:016x}",record.last_accessed.to_bits()))
    }).collect();
    ready(if direct {backend.clear(Some("written".into()))} else {crate::CandleCacheBackend::clear(&backend,Some("written".into()))}.expect("CACHE-FIXTURE concrete clear capability")).expect("CACHE-FIXTURE ready scoped clear");
    ready(if direct {backend.clear(None)} else {crate::CandleCacheBackend::clear(&backend,None)}.expect("CACHE-FIXTURE concrete clear-all capability")).expect("CACHE-FIXTURE ready namespace clear");
    serde_json::json!({"mode":mode,"load":load_projection,"all":listing_projection,"refusedKeys":loaded.refused_keys,"persisted":persisted,"calls":*store.calls.borrow(),"remainingKeys":store.values.borrow().keys().collect::<Vec<_>>()})
}

