assert!(std::ptr::eq(std::ops::Deref::deref(&backend),&backend.0),"CACHE-NATIVE actual wrapper deref");
    let options = crate::CandleCacheChunkAccessOptions {chunk_size:4,interval_seconds:60.0};
    let mode = $value.as_str().expect("authored direct/trait mode");
    assert!(matches!(mode,"direct"|"trait"),"CACHE-FIXTURE known call route");
    let direct = mode == "direct";
    let native = ready(if direct {backend.load_chunks("market".into(),vec![0,1,2,3],options)} else {crate::CandleCacheBackend::load_chunks(&backend,"market".into(),vec![0,1,2,3],options)}.expect("CACHE-FIXTURE concrete load capability")).expect("CACHE-FIXTURE ready load");
    assert_native(&native);
    let loaded = ready(if direct {backend.load_all_chunks("market".into(),options)} else {crate::CandleCacheBackend::load_all_chunks(&backend,"market".into(),options)}.expect("CACHE-FIXTURE concrete listing capability")).expect("CACHE-FIXTURE ready listing");
    assert_native(&loaded.chunks);
    assert_eq!(loaded.refused_keys,["review::market::9223372036854775808"],"CACHE-NATIVE independent refused source key");
    let load_projection = chunks(&native);
    let listing_projection = chunks(&loaded.chunks);
    // Every actual decoded load field assertion above runs BEFORE persist's
    // serialization or any subsequent persisted wire inspection.
    ready(if direct {backend.persist_chunks("written".into(),native,options)} else {crate::CandleCacheBackend::persist_chunks(&backend,"written".into(),native,options)}).expect("CACHE-FIXTURE ready persistence");
    let persisted:Vec<_> = store.writes.borrow().iter().map(|(key,raw)| {
        let record:crate::CandleCacheChunkRecord=serde_json::from_str(raw).expect("CACHE-FIXTURE persisted record JSON");
        (key.clone(),record.candles.iter().map(candle).collect::<Vec<_>>(),format!("{:016x}",record.last_accessed.to_bits()))
    }).collect();
    ready(if direct {backend.clear(Some("written".into()))} else {crate::CandleCacheBackend::clear(&backend,Some("written".into()))}.expect("CACHE-FIXTURE concrete clear capability")).expect("CACHE-FIXTURE ready scoped clear");
    ready(if direct {backend.clear(None)} else {crate::CandleCacheBackend::clear(&backend,None)}.expect("CACHE-FIXTURE concrete clear-all capability")).expect("CACHE-FIXTURE ready namespace clear");
    serde_json::json!({"mode":mode,"load":load_projection,"all":listing_projection,"refusedKeys":loaded.refused_keys,"persisted":persisted,"calls":*store.calls.borrow(),"remainingKeys":store.values.borrow().keys().collect::<Vec<_>>()})
}

